<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use Asyura\Auth;use Asyura\Security;use Asyura\View;
Auth::requireLogin($config['app_url']);Security::headers();if($_SERVER['REQUEST_METHOD']!=='POST'||!Security::verifyCsrf($_POST['csrf_token']??null)){http_response_code(403);exit('Invalid request');}$year=(int)($_POST['year']??0);if($year<2000||$year>(int)date('Y')){View::flash('対象年が正しくありません。','error');redirect(app_url('admin/?page=data'));}if(!class_exists('ZipArchive')){View::flash('PHP ZipArchive拡張が必要です。','error');redirect(app_url('admin/?page=data'));}
$start=sprintf('%04d-01-01 00:00:00',$year);$end=sprintf('%04d-01-01 00:00:00',$year+1);$definitions=['raw_events'=>['occurred_at'],'analytics_pageviews'=>['started_at'],'analytics_sessions'=>['started_at'],'conversion_events'=>['occurred_at'],'tracking_security_events'=>['last_seen_at'],'daily_visitors'=>['visit_date'],'daily_referrer_visitors'=>['visit_date'],'daily_stats'=>['stat_date'],'daily_link_stats'=>['stat_date'],'referrer_stats'=>['stat_date'],'rss_distribution_batches'=>['calculated_at'],'rss_distribution_history'=>['calculated_at'],'contact_messages'=>['created_at'],'link_requests'=>['created_at'],'notices'=>['created_at']];$fileName='asyura-'.$year.'-'.date('YmdHis').'.zip';$path=ASYURA_ROOT.'/storage/exports/'.$fileName;$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL)!==true){View::flash('エクスポートファイルを作成できません。','error');redirect(app_url('admin/?page=data'));}
foreach($definitions as $table=>[$column]){$tmp=tmpfile();if($tmp===false)continue;$stmt=$db->prepare("SELECT * FROM {$table} WHERE {$column}>=? AND {$column}<? ORDER BY {$column}");$stmt->execute([$start,$end]);$header=false;while($row=$stmt->fetch(PDO::FETCH_ASSOC)){if(!$header){fputcsv($tmp,array_keys($row));$header=true;}fputcsv($tmp,$row);}rewind($tmp);$csv=stream_get_contents($tmp);fclose($tmp);$zip->addFromString($table.'.csv',$csv?:'');}$zip->addFromString('README.txt',"阿修羅 年次エクスポート\n期間: {$year}-01-01 00:00:00 ～ {$year}-12-31 23:59:59\n作成: ".date('Y-m-d H:i:s')."\n");$zip->close();$size=filesize($path)?:0;$db->prepare('INSERT INTO exports (export_year,file_name,file_size) VALUES (?,?,?)')->execute([$year,$fileName,$size]);View::flash($year.'年のエクスポートを作成しました。');redirect(app_url('admin/?page=data'));
